-- Database Updates for Transfer Stock Module
-- Generated on 2026-07-11

-- ========================================================
-- 1. UPDATE TRIGGER FUNCTION: cbl_stock()
-- ========================================================
CREATE OR REPLACE FUNCTION public.cbl_stock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$

DECLARE

tmp RECORD;

stk RECORD;



pmp RECORD;

dernachat RECORD;

tik RECORD;

tikret RECORD;

	BEGIN

IF (TG_OP = 'DELETE') then

    select isstock as isstock,declinaison as declinaison into  tmp  from produits  where produitid=old.produitid limit 1;

  if(tmp.isstock) then

     if((select count(*) from stocks where produitid=old.produitid  and siteid=old.siteid)<1) then

        insert into stocks(stockid,produitid,siteid,qtestock) values (nextval('stocks_stockid_seq'),old.produitid,old.siteid,0);

     end if;

    if(TG_TABLE_NAME='detbontransferts') then

    if( (select count(*) from stocks where produitid=old.produitid and siteid=old.siterecepteurid)<1) then

            insert into stocks(stockid,produitid,siteid,qtestock) values (nextval('stocks_stockid_seq'),old.produitid,old.siterecepteurid,0);

    end if;

    end if;

      select stockid as stockid into  stk  from stocks  where produitid=old.produitid and  siteid=old.siteid   limit 1;

     if((select count(*) from stock2s where stockid=stk.stockid and produit2id=old.produit2id and siteid=old.siteid)<1) then

        insert into stock2s(stock2id,stockid,produitid,produit2id,siteid,qtestock,datedepart,qtedepart,qteentree,qtesortie) values (nextval('stock2s_stock2id_seq'),stk.stockid,old.produitid,old.produit2id,old.siteid,0,'0001-01-01 00:00:00'::timestamp without time zone,0,0,0);

     end if;

    if(TG_TABLE_NAME='detbontransferts') then

          select stockid as stockid into  stk  from stocks  where produitid=old.produitid and  siteid=old.siterecepteurid   limit 1;

         if((select count(*) from stock2s where stockid =stk.stockid and produit2id=old.produit2id and siteid=old.siterecepteurid)<1)then

        insert into stock2s(stock2id,stockid,produitid,produit2id,siteid,qtestock,datedepart,qtedepart,qteentree,qtesortie) values (nextval('stock2s_stock2id_seq'),stk.stockid,old.produitid,old.produit2id,old.siterecepteurid,0,'0001-01-01 00:00:00'::timestamp without time zone,0,0,0);

          end if;

    end if;

  end if;

  

 else

 select isstock as isstock,declinaison as declinaison into  tmp  from produits  where produitid=new.produitid limit 1;

     if(tmp.isstock) then

     if((select count(*) from stocks where produitid=new.produitid  and siteid=new.siteid)<1) then

        insert into stocks(stockid,produitid,siteid,qtestock) values (nextval('stocks_stockid_seq'),new.produitid,new.siteid,0);

     end if;

    if(TG_TABLE_NAME='detbontransferts') then 

    if((select count(*) from stocks where produitid=new.produitid and siteid=new.siterecepteurid)<1) then

            insert into stocks(stockid,produitid,siteid,qtestock) values (nextval('stocks_stockid_seq'),new.produitid,new.siterecepteurid,0);

     end if;

    end if;

    select stockid as stockid into  stk  from stocks  where produitid=new.produitid and  siteid=new.siteid   limit 1;

     if((select count(*) from stock2s where stockid=stk.stockid and produit2id=new.produit2id and siteid=new.siteid)<1) then

        insert into stock2s(stock2id,stockid,produitid,produit2id,siteid,qtestock,datedepart,qtedepart,qteentree,qtesortie) values (nextval('stock2s_stock2id_seq'),stk.stockid,new.produitid,new.produit2id,new.siteid,0,'0001-01-01 00:00:00'::timestamp without time zone,0,0,0);

     end if;

     if(TG_TABLE_NAME='detbontransferts') then

          select stockid as stockid into  stk  from stocks  where produitid=new.produitid and  siteid=new.siterecepteurid   limit 1;

         if((select count(*) from stock2s where stockid =stk.stockid and produit2id=new.produit2id and siteid=new.siterecepteurid)<1)then

        insert into stock2s(stock2id,stockid,produitid,produit2id,siteid,qtestock,datedepart,qtedepart,qteentree,qtesortie) values (nextval('stock2s_stock2id_seq'),stk.stockid,new.produitid,new.produit2id,new.siterecepteurid,0,'0001-01-01 00:00:00'::timestamp without time zone,0,0,0);

          end if;

    end if;

    

    end if;

end if;

if(tmp.isstock=false) then

return null;

end if;

IF (TG_OP = 'DELETE') then

update stock2s set qtestock=(select coalesce(sum(qte),0) from detfbls where  produit2id=old.produit2id and siteid=old.siteid)

+(select coalesce(sum(qte),0) from detffactures where  produit2id=old.produit2id and siteid=old.siteid and detfblid isnull)

-(select coalesce(sum(qte),0) from detfbrs where produit2id=old.produit2id and siteid=old.siteid)

   -(select coalesce(sum(qte),0) from detfavoirs  where produit2id=old.produit2id and siteid=old.siteid and detfbrid isnull)

     

-(select coalesce(sum(qte),0) from detcbls where  produit2id=old.produit2id and siteid=old.siteid)

-(select coalesce(sum(qte),0) from detctickets where retour=false and  produit2id=old.produit2id and siteid=old.siteid)

+(select coalesce(sum(qte),0) from detctickets where retour=true  and produit2id=old.produit2id and siteid=old.siteid)

-(select coalesce(sum(qte),0) from detcfactures where produit2id=old.produit2id and siteid=old.siteid and detcblid isnull and detcticketid is null)

+(select coalesce(sum(qte),0) from detcbrs where  produit2id=old.produit2id and siteid=old.siteid)

-(select coalesce(sum(qte),0) from detbonsorties where  produit2id=old.produit2id and siteid=old.siteid)

+(select coalesce(sum(qte),0) from detbonentrees where produit2id=old.produit2id and siteid=old.siteid)

+(select coalesce(sum(qterecu),0) from detbontransferts where produit2id=old.produit2id and siterecepteurid=old.siteid and etatbontransfertid=3)

-(select coalesce(sum(qteenvoi),0) from detbontransferts where  produit2id=old.produit2id and siteid=old.siteid and etatbontransfertid>1)

-(select coalesce(sum(-(ecart)),0) from public.detinventaires where  produit2id=old.produit2id and validee=true  and siteid=old.siteid)

where produitid=old.produitid and   produit2id=old.produit2id  and siteid=old.siteid;



update stock2s set entreeencour=(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=old.produitid and produit2id=old.produit2id and siterecepteurid=old.siteid and etatbontransfertid=2) where produitid=old.produitid and  produit2id=old.produit2id  and siteid=old.siteid;

update stock2s set sorieencour =(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=old.produitid and produit2id=old.produit2id and siteid=old.siteid and etatbontransfertid=2) where produitid=old.produitid and  produit2id=old.produit2id  and siteid=old.siteid;

update stock2s set stockvirtuel =qtestock +entreeencour  -stockreserve  where produitid=old.produitid and  produit2id=old.produit2id  and siteid=old.siteid;



if(TG_TABLE_NAME='detbontransferts') then

       update stock2s set qtestock=(select coalesce(sum(qte),0) from detfbls where produitid=old.produitid and produit2id=old.produit2id and siteid=old.siterecepteurid)

       +(select coalesce(sum(qte),0) from detffactures where  produit2id=old.produit2id and siteid=old.siterecepteurid and detfblid isnull)

       -(select coalesce(sum(qte),0) from detfbrs where produit2id=old.produit2id and siteid=old.siterecepteurid)

       -(select coalesce(sum(qte),0) from detfavoirs  where produit2id=old.produit2id and siteid=old.siterecepteurid and detfbrid isnull)

       -(select coalesce(sum(qte),0) from detcbls where  produit2id=old.produit2id and siteid=old.siterecepteurid)

       -(select coalesce(sum(qte),0) from detctickets where retour=false and  produit2id=old.produit2id and siteid=old.siterecepteurid)

       +(select coalesce(sum(qte),0) from detctickets where retour=true  and produit2id=old.produit2id and siteid=old.siterecepteurid)

       -(select coalesce(sum(qte),0) from detcfactures where produit2id=old.produit2id and siteid=old.siterecepteurid and detcblid isnull and detcticketid is null )

       +(select coalesce(sum(qte),0) from detcbrs where  produit2id=old.produit2id and siteid=old.siterecepteurid)

       -(select coalesce(sum(qte),0) from detbonsorties where  produit2id=old.produit2id and siteid=old.siterecepteurid)

       +(select coalesce(sum(qte),0) from detbonentrees where  produit2id=old.produit2id and siteid=old.siterecepteurid)

       +(select coalesce(sum(qterecu),0) from detbontransferts where produit2id=old.produit2id and siterecepteurid=old.siterecepteurid and etatbontransfertid=3)

       -(select coalesce(sum(qteenvoi),0) from detbontransferts where produit2id=old.produit2id and siteid=old.siterecepteurid and etatbontransfertid>1)

       -(select coalesce(sum(-(ecart)),0) from public.detinventaires where  produit2id=old.produit2id and validee=true  and siteid=old.siterecepteurid)

        where produitid=old.produitid  and  produit2id=old.produit2id  and siteid=old.siterecepteurid;

        update stock2s set entreeencour=(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=old.produitid and produit2id=old.produit2id and siterecepteurid=old.siterecepteurid and etatbontransfertid=2) where produitid=old.produitid and  produit2id=old.produit2id  and siteid=old.siterecepteurid;

       update stock2s set sorieencour =(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=old.produitid and produit2id=old.produit2id and siteid=old.siterecepteurid and etatbontransfertid=2) where produitid=old.produitid and  produit2id=old.produit2id  and siteid=old.siterecepteurid;

       update stock2s set stockvirtuel =qtestock +entreeencour  -stockreserve  where produitid=old.produitid and   produit2id=old.produit2id  and siteid=old.siterecepteurid;



      

       

 



end if;

if(TG_TABLE_NAME='detfbls' or TG_TABLE_NAME='detffactures') then

SELECT coalesce(sum(ht)/sum(qte),0) as pamp into pmp from ((select sum(totalhtnet) as ht,sum(qte) as qte   from detfbls  where produitid=old.produitid) union (select sum(totalhtnet) as ht ,sum(qte) as qte   from detffactures where produitid=old.produitid and detfblid isnull )  ) as pmp1 ;

SELECT coalesce(totalhtnet/qte,0) as ht,date  into dernachat from ( (select totalhtnet,qte,date   from detfbls  where produitid=old.produitid order by date desc limit 1) union (select totalhtnet ,qte,date    from detffactures where produitid=old.produitid and detfblid isnull order by date desc limit 1 ) )   as pmp2 order by date desc limit 1  ;

update produits set pamp=pmp.pamp,dernachat=case coalesce(dernachat.ht,0)>0 when true then coalesce(dernachat.ht,0) else ht_achat *(1-remise_achat /100) end where produitid=old.produitid;

end if;

RETURN OLD;

else



update stock2s set qtestock=(select coalesce(sum(qte),0) from detfbls where  produit2id=new.produit2id and siteid=new.siteid)

+(select coalesce(sum(qte),0) from detffactures where  produit2id=new.produit2id and siteid=new.siteid and detfblid isnull)

-(select coalesce(sum(qte),0) from detfbrs where produit2id=new.produit2id and siteid=new.siteid)

   -(select coalesce(sum(qte),0) from detfavoirs  where produit2id=new.produit2id and siteid=new.siteid and detfbrid isnull)

     

-(select coalesce(sum(qte),0) from detcbls where  produit2id=new.produit2id and siteid=new.siteid)

-(select coalesce(sum(qte),0) from detctickets where retour=false and  produit2id=new.produit2id and siteid=new.siteid)

+(select coalesce(sum(qte),0) from detctickets where retour=true  and produit2id=new.produit2id and siteid=new.siteid)

-(select coalesce(sum(qte),0) from detcfactures where produit2id=new.produit2id and siteid=new.siteid and detcblid isnull and detcticketid is null)

+(select coalesce(sum(qte),0) from detcbrs where  produit2id=new.produit2id and siteid=new.siteid)

-(select coalesce(sum(qte),0) from detbonsorties where  produit2id=new.produit2id and siteid=new.siteid)

+(select coalesce(sum(qte),0) from detbonentrees where produit2id=new.produit2id and siteid=new.siteid)

+(select coalesce(sum(qterecu),0) from detbontransferts where produit2id=new.produit2id and siterecepteurid=new.siteid and etatbontransfertid=3)

-(select coalesce(sum(qteenvoi),0) from detbontransferts where  produit2id=new.produit2id and siteid=new.siteid and etatbontransfertid>1)

-(select coalesce(sum(-(ecart)),0) from public.detinventaires where  produit2id=new.produit2id and validee=true  and siteid=new.siteid)

where produitid=new.produitid and produit2id=new.produit2id  and siteid=new.siteid;

update stock2s set entreeencour=(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=new.produitid and produit2id=new.produit2id and siterecepteurid=new.siteid and etatbontransfertid=2) where produitid=new.produitid and  produit2id=new.produit2id  and siteid=new.siteid;

update stock2s set sorieencour =(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=new.produitid and produit2id=new.produit2id and siteid=new.siteid and etatbontransfertid=2) where produitid=new.produitid and  produit2id=new.produit2id  and siteid=new.siteid;

update stock2s set stockvirtuel =qtestock +entreeencour  -stockreserve  where produitid=new.produitid and   produit2id=new.produit2id  and siteid=new.siteid;

 

if(TG_TABLE_NAME='detbontransferts') then

        update stock2s set qtestock=(select coalesce(sum(qte),0) from detfbls where produitid=new.produitid and produit2id=new.produit2id and siteid=new.siterecepteurid)

       +(select coalesce(sum(qte),0) from detffactures where  produit2id=new.produit2id and siteid=new.siterecepteurid and detfblid isnull)

       -(select coalesce(sum(qte),0) from detfbrs where produit2id=new.produit2id and siteid=new.siterecepteurid)

        -(select coalesce(sum(qte),0) from detfavoirs  where produit2id=new.produit2id and siteid=new.siterecepteurid and detfbrid isnull)

       -(select coalesce(sum(qte),0) from detcbls where  produit2id=new.produit2id and siteid=new.siterecepteurid)

       -(select coalesce(sum(qte),0) from detctickets where retour=false and  produit2id=new.produit2id and siteid=new.siterecepteurid)

       +(select coalesce(sum(qte),0) from detctickets where retour=true  and produit2id=new.produit2id and siteid=new.siterecepteurid)

       -(select coalesce(sum(qte),0) from detcfactures where produit2id=new.produit2id and siteid=new.siterecepteurid and detcblid isnull and detcticketid is null )

       +(select coalesce(sum(qte),0) from detcbrs where  produit2id=new.produit2id and siteid=new.siterecepteurid)

       -(select coalesce(sum(qte),0) from detbonsorties where  produit2id=new.produit2id and siteid=new.siterecepteurid)

       +(select coalesce(sum(qte),0) from detbonentrees where  produit2id=new.produit2id and siteid=new.siterecepteurid)

       +(select coalesce(sum(qterecu),0) from detbontransferts where produit2id=new.produit2id and siterecepteurid=new.siterecepteurid and etatbontransfertid=3)

       -(select coalesce(sum(qteenvoi),0) from detbontransferts where produit2id=new.produit2id and siteid=new.siterecepteurid and etatbontransfertid>1)

       -(select coalesce(sum(-(ecart)),0) from public.detinventaires where  produit2id=new.produit2id and validee=true  and siteid=new.siterecepteurid)

       where produitid=new.produitid  and  produit2id=new.produit2id  and siteid=new.siterecepteurid;

       update stock2s set entreeencour=(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=new.produitid and produit2id=new.produit2id and siterecepteurid=new.siterecepteurid and etatbontransfertid=2) where produitid=new.produitid and  produit2id=new.produit2id  and siteid=new.siterecepteurid;

       update stock2s set sorieencour =(select coalesce(sum(qteenvoi),0) from detbontransferts where produitid=new.produitid and produit2id=new.produit2id and siteid=new.siterecepteurid and etatbontransfertid=2) where produitid=new.produitid and  produit2id=new.produit2id  and siteid=new.siterecepteurid;

       update stock2s set stockvirtuel =qtestock +entreeencour  -stockreserve  where produitid=new.produitid and   produit2id=new.produit2id  and siteid=new.siterecepteurid;

  

 end if;

if(TG_TABLE_NAME='detfbls' or TG_TABLE_NAME='detffactures') then

SELECT coalesce(sum(ht)/sum(qte),0) as pamp into pmp from ((select sum(totalhtnet) as ht,sum(qte) as qte   from detfbls  where produitid=new.produitid) union (select sum(totalhtnet) as ht ,sum(qte) as qte   from detffactures where produitid=new.produitid and detfblid isnull )  ) as pmp1 ;

SELECT coalesce(totalhtnet/qte,0) as ht,date  into dernachat from ( (select totalhtnet,qte,date   from detfbls  where produitid=new.produitid order by date desc limit 1) union (select totalhtnet ,qte,date    from detffactures where produitid=new.produitid and detfblid isnull order by date desc limit 1 ) )   as pmp2 order by date desc limit 1  ;

update produits set pamp=pmp.pamp,dernachat=case coalesce(dernachat.ht,0)>0 when true then coalesce(dernachat.ht,0) else ht_achat *(1-remise_achat /100) end where produitid=new.produitid;

end if;

RETURN NEW;

end if;

END;

$function$

;

-- ========================================================
-- 2. UPDATE FUNCTION OVERLOADS: getjournalproduit()
-- ========================================================
CREATE OR REPLACE FUNCTION public.getjournalproduit(pid bigint DEFAULT NULL::bigint, pclientid bigint DEFAULT NULL::bigint, pfournisseurid bigint DEFAULT NULL::bigint, datedebut timestamp without time zone DEFAULT NULL::timestamp without time zone, datefin timestamp without time zone DEFAULT NULL::timestamp without time zone, isvente boolean DEFAULT true, isachat boolean DEFAULT true, isstock boolean DEFAULT true, isjournalstock boolean DEFAULT false, psiteid integer[] DEFAULT NULL::integer[], pfamille integer[] DEFAULT NULL::integer[], psfamille integer[] DEFAULT NULL::integer[], documents integer[] DEFAULT '{}'::integer[], ptransfere boolean DEFAULT true, ignoreticket boolean DEFAULT false, isalldocument boolean DEFAULT true)                                                                                                                                                                                                                                                                                                                                               
RETURNS TABLE(vdetid bigint, vtypeid integer, vfamilleid integer, vsousfamilleid integer, vproduitid bigint, vsiteid integer, vtierid bigint, vproduitcode text, vproduitlibelle text, vdate timestamp without time zone, vdocid bigint, vpiecetype text, vdoctype text, vcommercial text, vdescription text, vdoclibelle text, vtiers text, vdocnumero bigint, vqteentree numeric, vqtesortie numeric, vqtediff numeric, vqtetrans numeric, vht numeric, vttc numeric, vtotalht numeric, vremise numeric, vtotalhtnet numeric, vtva numeric, vtaxe1 numeric, vtaxe2 numeric, vtotalttc numeric, vfamille text, vsousfamille text, vtaille text, vcouleur text, vdocorigin text, vsitelibelle text)                                                                                                                                                                                                                                                                                                                                                                                                            
LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
if(isalldocument=true)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
documents= '{}';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
create temporary table temp_journalproduits on commit drop  as select transfere, detid, typeid, familleid, sousfamilleid, produitid, siteid, clientid, produitcode, produitlibelle, "date", docid, piecetype, doctype, commercial, description, doclibelle, tiers, docnumero, qte,qte2,qtediff, qtetrans, ht, ttc, totalht, remise, totalhtnet, tva, taxe1, taxe2, totalttc, valeurht, valeurttc, margeht, margettc, totalmargeht, totalmargettc, '' as famille,'' as sousfamille,'' as taille,'' as couleur ,'' as docorigine1,'' as sitelibelle from journalproduits where 1=2;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
if(isvente)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
if(isjournalstock=false)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
if(0 =ANY(documents::int[]) or documents= '{}')then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
INSERT INTO temp_journalproduits(transfere, detid, typeid, familleid, sousfamilleid, produitid, siteid, clientid, produitcode, produitlibelle, "date", docid, piecetype, doctype, commercial, description, doclibelle, tiers, docnumero, qte,qte2,qtediff, qtetrans, ht, ttc, totalht, remise, totalhtnet, tva, taxe1, taxe2, totalttc, valeurht, valeurttc, margeht, margettc, totalmargeht, totalmargettc,famille,sousfamille,taille,couleur,docorigine1,sitelibelle)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
