CREATE OR REPLACE FUNCTION public.getjournalproduit(pid bigint DEFAULT NULL::bigint, pclientid bigint DEFAULT NULL::bigint, pfournisseurid bigint DEFAULT NULL::bigint, datedebut timestamp without time zone DEFAULT NULL::timestamp without time zone, datefin timestamp without time zone DEFAULT NULL::timestamp without time zone, isvente boolean DEFAULT true, isachat boolean DEFAULT true, isstock boolean DEFAULT true, isjournalstock boolean DEFAULT false, psiteid integer[] DEFAULT NULL::integer[], pfamille integer[] DEFAULT NULL::integer[], psfamille integer[] DEFAULT NULL::integer[], documents integer[] DEFAULT '{}'::integer[], ptransfere boolean DEFAULT true, ignoreticket boolean DEFAULT false, isalldocument boolean DEFAULT true, pcategoryid integer[] DEFAULT NULL::integer[], pcategory4id integer[] DEFAULT NULL::integer[])                                                                                                                                                                                                                                                
RETURNS TABLE(vdetid bigint, vtypeid integer, vfamilleid integer, vsousfamilleid integer, vproduitid bigint, vsiteid integer, vtierid bigint, vproduitcode text, vproduitlibelle text, vdate timestamp without time zone, vdocid bigint, vpiecetype text, vdoctype text, vcommercial text, vdescription text, vdoclibelle text, vtiers text, vdocnumero bigint, vqteentree numeric, vqtesortie numeric, vqtediff numeric, vqtetrans numeric, vht numeric, vttc numeric, vtotalht numeric, vremise numeric, vtotalhtnet numeric, vtva numeric, vtaxe1 numeric, vtaxe2 numeric, vtotalttc numeric, vtotalttcnet numeric, vfamille text, vsousfamille text, vtaille text, vcouleur text, vdocorigin text, vsitelibelle text, vcategoryid integer, vcategory4id integer, vcategorylibelle text, vcategory4libelle text, vreference text, vsiterecepteurid integer, vsiterecepteurlibelle text, vfrsid bigint, vfrslibelle text)                                                                                                                                                                                    
