AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 
begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
if(isalldocument=true)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
documents= '{}';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
create temporary table temp_journalproduits on commit drop  as select transfere, detid, typeid, familleid, sousfamilleid, produitid, siteid, clientid, produitcode, produitlibelle, "date", docid, piecetype, doctype, commercial, description, doclibelle, tiers, docnumero, qte,qte2,qtediff, qtetrans, ht, ttc, totalht, remise, totalhtnet, tva, taxe1, taxe2, totalttc,totalttcnet, valeurht, valeurttc, margeht, margettc, totalmargeht, totalmargettc, '' as famille,'' as sousfamille,'' as taille,'' as couleur ,'' as docorigine1,'' as sitelibelle,categoryid,category4id,categorylibelle,category4libelle,reference, 0 as siterecepteurid,'' siterecepteurlibelle,0::Bigint as frsid,'' as frslibelle from journalproduits where 1=2;                                                                                                                                                                                                                                                                                                                                                             
if(isvente)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               
if(isjournalstock=false)then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                
